//! ♻️ Actual clone close-frame private custody preserves original terminal release laws.
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use super::*;
use crate::observe_retirement_allocations;
use crate::observe_retirement_allocations as observe;

struct ScalarClose{cursor:crate::retained_clone::ScalarCursor<u64>}
#[derive(Clone,Copy)]enum Operation{Start,Close(usize)}
impl OriginalEffectProducer for ScalarClose{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Operation where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Operation)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Operation)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,op:&mut Operation,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match op{Operation::Start=>self.cursor.begin_close_into(effect,reply),Operation::Close(body)=>self.cursor.close_into(*body,effect,reply)}}
 fn recover<'r,'a,'b>(&mut self,op:&mut Operation,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match op{Operation::Start=>self.cursor.recover_begin_close_into(effect,reply),Operation::Close(body)=>self.cursor.recover_close_into(*body,effect,reply)}}
}
fn run(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<ScalarClose>,op:Operation,grant:RetainedCloneGrant,units:u64)->(RetainedCloneStep,(usize,usize)){
 let mut action=None;let mut answer=None;let mut operation=op;let ((poll,actual),heap)=observe_retirement_allocations(||bank.run(grant,units,|effect|{let before=effect.performed_work();let ready=authority.drive(&mut operation,effect,&mut action);let work=effect.performed_work()-before;match ready{Ok(true)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work}),Ok(false)=>RetainedWorkPoll::Pending{work},Err(error)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error),work})}}));
 let RetainedWorkPoll::Complete(turn)=poll else{panic!("scalar close fixture retained an unresolved action")};turn.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();let step=answer.unwrap().unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,heap);(step,heap)
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]
fn retained_clone_close_depth_observes_pending_birth_and_preserves_owner_on_refusal(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🧪️tests/🧫️fixtures/🪜️close-demands/🔣️.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:1048576,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:33554432,maximum_depth:256};let mut bank=EffectBank::new(Wallet::new(stock,1048576));let mut cursor=crate::retained_clone::ScalarCursor::<u64>::default();cursor.value=Some(law["owner"].as_u64().unwrap());let mut authority=Some(OriginalEffectAuthority::new(ScalarClose{cursor}));
 assert_eq!(authority.as_ref().unwrap().inspect(|p|p.cursor.next_close_depth_demand().unwrap()),law["idleDepth"].as_u64().unwrap()as usize);
 let d=authority.as_ref().unwrap().inspect(|p|p.cursor.begin_close_demand().unwrap());let work=authority.as_ref().unwrap().inspect(|p|p.cursor.begin_close_work_demand().unwrap());run(&mut bank,authority.as_mut().unwrap(),Operation::Start,grant(d),work);
 let ((depth,capacity),heap)=observe_retirement_allocations(||authority.as_ref().unwrap().inspect(|p|(p.cursor.next_close_depth_demand().unwrap(),p.cursor.next_close_capacity_byte_demand(0).unwrap())));assert_eq!(heap,(0,0));assert_eq!(depth,law["pendingBirthDepth"].as_u64().unwrap()as usize);
 let denied=RetainedCloneGrant{maximum_items:law["refusedBirth"]["maximumItems"].as_u64().unwrap()as usize,maximum_capacity_bytes:capacity,maximum_depth:law["refusedBirth"]["maximumDepth"].as_u64().unwrap()as usize,..Default::default()};let units=authority.as_ref().unwrap().inspect(|p|p.cursor.close_work_demand(0).unwrap());let(step,heap)=run(&mut bank,authority.as_mut().unwrap(),Operation::Close(0),denied,units);assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert_eq!(authority.as_ref().unwrap().inspect(|p|p.cursor.value),Some(law["owner"].as_u64().unwrap()));
 let birth=RetainedCloneGrant{maximum_items:law["fundedBirth"]["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:authority.as_ref().unwrap().inspect(|p|p.cursor.next_close_copy_byte_demand().unwrap()),maximum_capacity_bytes:capacity,maximum_depth:depth,..Default::default()};let(step,heap)=run(&mut bank,authority.as_mut().unwrap(),Operation::Close(0),birth,units);assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(birth));assert!(authority.as_ref().unwrap().inspect(|p|p.cursor.value.is_none()));
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if authority.as_ref().unwrap().inspect(|p|p.cursor.terminal_is_empty()){break}let d=authority.as_ref().unwrap().inspect(|p|p.cursor.close_demands(4096).unwrap());let issued=grant(d);assert_eq!(authority.as_ref().unwrap().inspect(|p|p.cursor.close_demands(issued.maximum_copy_bytes).unwrap()),d);let units=authority.as_ref().unwrap().inspect(|p|p.cursor.close_work_demand(4096).unwrap());let(step,heap)=run(&mut bank,authority.as_mut().unwrap(),Operation::Close(4096),issued,units);assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(authority.as_ref().unwrap().inspect(|p|p.cursor.terminal_is_empty()));assert_eq!(authority.as_ref().unwrap().inspect(|p|p.cursor.next_close_depth_demand().unwrap()),law["terminalDepth"].as_u64().unwrap()as usize);
 let mut producer=None;let d=OriginalEffectAuthority::<ScalarClose>::producer_transfer_demand().unwrap();let issued=grant(d);let ((poll,actual),heap)=observe_retirement_allocations(||bank.run(issued,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&Operation::Close(4096),&mut producer,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("scalar producer transfer pending")};let progress=turn.result.unwrap().unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,issued,heap);
 let witness=unsafe{RetainedCursorRelease::native(|p:&ScalarClose|p.cursor.native_terminal_release().is_some_and(|witness|witness.validates(&p.cursor)))};assert!(witness.validates(producer.as_ref().unwrap()));let issued=grant(witness.inline_demand());let mut reply=None;let ((poll,actual),heap)=observe_retirement_allocations(||bank.run(issued,witness.inline_work(),|effect|{let before=effect.performed_work();let complete=witness.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap();drop(complete);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("scalar producer release pending")};turn.result.unwrap();let progress=reply.take().unwrap().unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,issued,heap);assert!(producer.is_none());
}

#[derive(Clone,Copy)]enum CapturedOp{First,Second,Proof,CloseFirst,CloseSecond,TakeFirst,ClearOutput}
struct CapturedParent{first:RetainedFieldCursor<u64>,second:RetainedFieldCursor<u64>,proof:Option<(bool,bool,bool)>,output:Option<u64>,native_reply:Option<Result<RetainedCloneStep,ValueError>>}
impl CapturedParent{
 fn empty(&self)->bool{self.first.terminal_is_empty()&&self.second.terminal_is_empty()&&self.output.is_none()&&self.native_reply.is_none()}
 fn quote(&self,source:RetainedCloneRef<'_,u64>,op:CapturedOp)->(RetirementDemand,u64){
  let cursor=match op{CapturedOp::First|CapturedOp::CloseFirst=>&self.first,CapturedOp::Second|CapturedOp::CloseSecond=>&self.second,CapturedOp::TakeFirst=>return(self.first.take_demand().unwrap(),self.first.take_work_demand().unwrap()),CapturedOp::ClearOutput=>return(RetirementDemand{copy_bytes:std::mem::size_of::<Option<u64>>(),depth:1,..Default::default()},1),CapturedOp::Proof=>return(RetirementDemand{copy_bytes:std::mem::size_of::<Option<(bool,bool,bool)>>(),depth:1,..Default::default()},1)};
  if matches!(op,CapturedOp::First|CapturedOp::Second){(cursor.advance_demands(source,4096,4096).unwrap(),cursor.advance_work_demand(source,4096,4096).unwrap())}else if !cursor.close_started(){(cursor.begin_close_demand().unwrap(),cursor.begin_close_work_demand().unwrap())}else{(cursor.close_bound_demands(source,4096).unwrap(),cursor.close_bound_work_demand(source,4096).unwrap())}
 }
}
impl OriginalEffectProducer for CapturedParent{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(RetainedCloneRef<'a,u64>,OriginalSourceTurnIdentity,CapturedOp)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{
  match c.2{CapturedOp::TakeFirst=>{drop(self.first.take(&mut self.output,e,OriginalEffectReply::borrow(&mut self.native_reply)?)?);crate::forward_original_value_reply(&mut self.native_reply,r)},CapturedOp::ClearOutput=>{if !e.performed(1)?{return Err(ValueError::invariant("captured output clear work denied"))}self.output=None;Ok(r.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of_val(&self.output),..Default::default()}))))},CapturedOp::First=>self.first.advance_into(c.0,4096,4096,e,r),CapturedOp::Second=>self.second.advance_into(c.0,4096,4096,e,r),CapturedOp::Proof=>{let accepted=self.first.test_captured_dispatch(&self.second,e)?;if !e.performed(1)?{return Err(ValueError::invariant("captured proof header work denied"))}self.proof=Some(accepted);Ok(r.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of_val(&self.proof),..Default::default()}))))},CapturedOp::CloseFirst|CapturedOp::CloseSecond=>{let cursor=if matches!(c.2,CapturedOp::CloseFirst){&mut self.first}else{&mut self.second};if !cursor.close_started(){cursor.begin_close_into(e,r)}else{cursor.close_bound_into(c.0,4096,e,r)}}}
 }
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{
  match c.2{CapturedOp::First=>self.first.recover_advance_into(c.0,4096,4096,e,r),CapturedOp::Second=>self.second.recover_advance_into(c.0,4096,4096,e,r),CapturedOp::CloseFirst=>self.first.recover_close_bound_into(c.0,4096,e,r),CapturedOp::CloseSecond=>self.second.recover_close_bound_into(c.0,4096,e,r),CapturedOp::TakeFirst=>{if self.native_reply.is_none(){drop(self.first.recover_take(&mut self.output,e,OriginalEffectReply::borrow(&mut self.native_reply)?)?)}crate::forward_original_value_reply(&mut self.native_reply,r)},CapturedOp::ClearOutput|CapturedOp::Proof=>Err(ValueError::invariant("native proof or clear has no unrecorded reply"))}
 }
}
fn captured_parent_turn(source:&mut FixtureSource<u64>,authority:&mut OriginalEffectAuthority<CapturedParent>,op:CapturedOp){let _=captured_parent_turn_at_depth(source,authority,op,usize::MAX);}
fn captured_parent_turn_at_depth(source:&mut FixtureSource<u64>,authority:&mut OriginalEffectAuthority<CapturedParent>,op:CapturedOp,depth:usize)->(RetainedCloneStep,(usize,usize),u128){
 let(d,units)=authority.inspect(|p|p.quote(source.borrow(),op));let(mut action,mut answer)=(None,None);let mut observed=(0,0);let mut spent=0;
 source.with_bank(|original,bank|{let mut issued=bank.loan(1,d.copy_bytes);issued.maximum_depth=issued.maximum_depth.min(depth);for _ in 0..64{let((poll,actual),heap)=observe_retirement_allocations(||bank.run_with_source(issued,units,|effect,turn|{let before=effect.performed_work();let mut context=(original,turn.identity(),op);let ready=authority.drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));observed.0+=heap.0;observed.1+=heap.1;spent+=poll.work();if let Some(actual)=actual{assert_eq!(actual,observed.0)}if let RetainedWorkPoll::Complete(turn)=poll{turn.result.unwrap();assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();break}}let step=answer.take().unwrap().unwrap();assert_eq!(bank.take_admitted(),if spent==0{None}else{Some(true)});bank.post(step.progress(),issued,observed);(step,observed,spent)}).unwrap()
}
#[test]
fn captured_field_keeps_its_actual_child_projection_and_rejects_replacements(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🔗️source/🎟️admission/captured-source.json")).unwrap();let mut source=RetainedCloneSource::from_owner(73u64);let mut foreign=RetainedCloneSource::from_owner(73u64);let mut authority=Some(OriginalEffectAuthority::new(CapturedParent{first:Default::default(),second:Default::default(),proof:None,output:None,native_reply:None}));
 for op in [CapturedOp::First,CapturedOp::Second]{for _ in 0..RetainedFieldCursor::<u64>::native_birth_prefix_actions().unwrap(){captured_parent_turn(&mut source,authority.as_mut().unwrap(),op)}}
 let before=source.wallet().remaining_work();captured_parent_turn(&mut source,authority.as_mut().unwrap(),CapturedOp::Proof);assert_eq!(before-source.wallet().remaining_work(),law["proofWork"].as_u64().unwrap());
 authority.as_ref().unwrap().inspect(|p|{assert_eq!(p.proof,Some((law["sameChild"].as_bool().unwrap(),law["foreignChild"].as_bool().unwrap(),law["wrongMode"].as_bool().unwrap())));assert!(p.first.authenticate_source(source.borrow()).is_ok());assert_eq!(p.first.authenticate_source(foreign.borrow()).is_ok(),law["foreignSource"].as_bool().unwrap());assert_eq!(p.first.authenticate_source(source.borrow().project(7,|value|value)).is_ok(),law["foreignPath"].as_bool().unwrap());});
 for op in [CapturedOp::CloseFirst,CapturedOp::CloseSecond]{for _ in 0..128{let empty=authority.as_ref().unwrap().inspect(|p|if matches!(op,CapturedOp::CloseFirst){p.first.terminal_is_empty()}else{p.second.terminal_is_empty()});if empty{break}captured_parent_turn(&mut source,authority.as_mut().unwrap(),op)}}
 assert!(authority.as_ref().unwrap().inspect(CapturedParent::empty));finish_captured_parent(&mut source,&mut authority);
 for source in [&mut source,&mut foreign]{for _ in 0..128{if source.terminal_is_empty(){break}assert!(!matches!(source.close_once().unwrap(),semio_framework_value_clone_source_testing::FixtureCloseStep::Denied|semio_framework_value_clone_source_testing::FixtureCloseStep::Blocked));}assert!(source.terminal_is_empty())}
}

fn finish_captured_parent(source:&mut FixtureSource<u64>,authority:&mut Option<OriginalEffectAuthority<CapturedParent>>){let mut producer=None;source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<CapturedParent>::producer_transfer_demand().unwrap();let issued=bank.loan(1,d.copy_bytes);let((poll,actual),heap)=observe_retirement_allocations(||bank.run_with_source(issued,1,|effect,turn|{let context=(original,turn.identity(),CapturedOp::Proof);RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("captured producer transfer pending")};let progress=turn.result.unwrap().unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,issued,heap);
 let release=unsafe{RetainedCursorRelease::native(CapturedParent::empty)};let issued=bank.loan(1,release.inline_demand().copy_bytes);let mut reply=None;let((poll,actual),heap)=observe_retirement_allocations(||bank.run(issued,release.inline_work(),|effect|{let before=effect.performed_work();drop(release.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("captured producer clear pending")};turn.result.unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(bank.take_admitted(),Some(true));bank.post(reply.take().unwrap().unwrap().progress(),issued,heap);}).unwrap();assert!(producer.is_none());}

#[test]
fn captured_field_metadata_is_transparent_at_the_actual_leaf_boundary(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🔗️source/🎟️admission/depth.json")).unwrap();let mut source=RetainedCloneSource::from_owner(law["leafValue"].as_u64().unwrap());let mut authority=Some(OriginalEffectAuthority::new(CapturedParent{first:Default::default(),second:Default::default(),proof:None,output:None,native_reply:None}));
 for _ in 0..64{if authority.as_ref().unwrap().inspect(|p|p.first.output_ready()){break}let(d,_)=authority.as_ref().unwrap().inspect(|p|p.quote(source.borrow(),CapturedOp::First));assert!(d.depth<=law["leafDepth"].as_u64().unwrap()as usize,"metadata wrapper added a payload depth: {d:?}");captured_parent_turn_at_depth(&mut source,authority.as_mut().unwrap(),CapturedOp::First,1);}
 assert!(authority.as_ref().unwrap().inspect(|p|p.first.output_ready()));let before=source.wallet().remaining_work();let(step,heap,work)=captured_parent_turn_at_depth(&mut source,authority.as_mut().unwrap(),CapturedOp::TakeFirst,0);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(before,source.wallet().remaining_work());assert!(authority.as_ref().unwrap().inspect(|p|p.first.output_ready()&&p.output.is_none()));let(d,_)=authority.as_ref().unwrap().inspect(|p|p.quote(source.borrow(),CapturedOp::TakeFirst));assert_eq!(d.depth,1);captured_parent_turn_at_depth(&mut source,authority.as_mut().unwrap(),CapturedOp::TakeFirst,1);assert_eq!(authority.as_ref().unwrap().inspect(|p|p.output),Some(law["leafValue"].as_u64().unwrap()));captured_parent_turn_at_depth(&mut source,authority.as_mut().unwrap(),CapturedOp::ClearOutput,1);
 for op in [CapturedOp::CloseFirst,CapturedOp::CloseSecond]{for _ in 0..128{let empty=authority.as_ref().unwrap().inspect(|p|if matches!(op,CapturedOp::CloseFirst){p.first.terminal_is_empty()}else{p.second.terminal_is_empty()});if empty{break}let(d,_)=authority.as_ref().unwrap().inspect(|p|p.quote(source.borrow(),op));assert!(d.depth<=1,"metadata close added a payload depth: {d:?}");captured_parent_turn_at_depth(&mut source,authority.as_mut().unwrap(),op,1);}}
 finish_captured_parent(&mut source,&mut authority);for _ in 0..128{if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());
}

#[path="../../🔤️string-cursor/🧪️tests/producer.rs"]mod depth_producer;
#[test]
fn vector_payload_child_uses_one_genuine_depth_edge(){
 use depth_producer::{Harness,Op};let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🔗️source/🎟️admission/depth.json")).unwrap();let mut source=RetainedCloneSource::from_owner(vec!["xy".to_owned()]);let pointer=source.borrow().get().as_ptr();let mut cursor=Harness::<Vec<String>>::new(&source);let mut reached=false;
 for _ in 0..64{let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(&source,Op::Advance,4096,maximum);let mut grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();if d.depth>1{assert_eq!(d.depth,law["childDepth"].as_u64().unwrap()as usize);grant.maximum_depth=1;let before=source.wallet().remaining_work();let(step,heap)=cursor.drive(&mut source,Op::Advance,4096,maximum,grant,work);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(before,source.wallet().remaining_work());assert_eq!(source.borrow().get().as_ptr(),pointer);grant.maximum_depth=2;let(step,heap)=cursor.drive(&mut source,Op::Advance,4096,maximum,grant,work);assert!(step.progress().copied_items>0);assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));reached=true;break}grant.maximum_depth=1;cursor.drive(&mut source,Op::Advance,4096,maximum,grant,work);}
 assert!(reached);for _ in 0..128{if cursor.ready(){break}let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(&source,Op::Advance,4096,maximum);assert!(d.depth<=2);let mut grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();grant.maximum_depth=2;cursor.drive(&mut source,Op::Advance,4096,maximum,grant,work);}assert!(cursor.ready());let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(&source,Op::Take,0,maximum);let grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();cursor.drive(&mut source,Op::Take,0,maximum,grant,work);cursor.inspect_output(|value|assert_eq!(value.unwrap(),&vec!["xy".to_owned()]));
 finish_depth_harness(&mut source,&mut cursor);assert_eq!(observe_retirement_allocations(||drop(cursor)).1,(0,0));for _ in 0..128{if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());assert_eq!(observe_retirement_allocations(||drop(source)).1,(0,0));
}

fn finish_depth_harness<T:RetainedClone>(source:&mut FixtureSource<T>,cursor:&mut depth_producer::Harness<T>){use depth_producer::Op; for op in [Op::Start,Op::BoundClose]{for _ in 0..128{if cursor.terminal(){break}let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(source,op,4096,maximum);let grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();cursor.drive(source,op,4096,maximum,grant,work);if matches!(op,Op::Start){break}}}assert!(cursor.terminal());for _ in 0..256{if !cursor.has_output()&&cursor.output_close_empty(){break}let op=if cursor.has_output(){Op::OutputStart}else{Op::OutputClose};let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(source,op,4096,maximum);let grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();cursor.drive(source,op,4096,maximum,grant,work);}assert!(!cursor.has_output()&&cursor.output_close_empty());cursor.release(source);}

#[test]
fn paired_captured_selection_visits_each_controller_once(){
 use depth_producer::{Harness,Op};let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🔗️source/🎟️admission/selection.json")).unwrap();let mut owner=crate::DslValue::Number(crate::Number::UInt(73));for _ in 0..law["arrayEdges"].as_u64().unwrap(){owner=crate::DslValue::Array(vec![owner])}let mut source=RetainedCloneSource::from_owner(owner);let mut cursor=Harness::<crate::DslValue>::new(&source);let bound=law["maximumSelectors"].as_u64().unwrap()as usize;
 for _ in 0..256{if cursor.ready(){break}let maximum=source.wallet().remaining_work().min(law["perTurnWork"].as_u64().unwrap());crate::retained_clone::selection_observation::begin();let(d,work)=cursor.quote(&source,Op::Advance,4096,maximum);let visits=crate::retained_clone::selection_observation::finish();assert!(visits>0&&visits<=bound,"paired quote repeated a native controller: {visits}");let grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();crate::retained_clone::selection_observation::begin();let(step,heap)=cursor.drive(&mut source,Op::Advance,4096,maximum,grant,work);let visits=crate::retained_clone::selection_observation::finish();assert!(visits>0&&visits<=bound,"native dispatch reselected its captured frontier: {visits}");assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(cursor.ready());let maximum=source.wallet().remaining_work().min(4096);let(d,work)=cursor.quote(&source,Op::Take,0,maximum);let grant=source.with_bank(|_,bank|bank.loan(1,d.copy_bytes)).unwrap();cursor.drive(&mut source,Op::Take,0,maximum,grant,work);finish_depth_harness(&mut source,&mut cursor);assert_eq!(observe(||drop(cursor)).1,(0,0));for _ in 0..128{if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());assert_eq!(observe(||drop(source)).1,(0,0));
}
